prompt:
The library function `u5::d056` returns how many transfers succeeded but its contract does not bound that number. Add to its postcondition that the result is at most a.len(), keeping everything else.

Required signature (in unit `u5`):
fn d056(a: &mut [i64], from: usize, x: i64) -> (r: usize)

reference.code:
spec fn paid_ok(a: &[i64], r: usize) -> bool { r <= a.len() }

#[effects(pure)]
#[uses(d051, d048, d049, paid_ok)]
fn d056(a: &mut [i64], from: usize, x: i64) -> (r: usize)
    requires d051(a), d048(a, from), d049(x),
    ensures d051(a), paid_ok(a, r),
{
    let mut paid: usize = 0;
    let mut k: usize = 0;
    while k < a.len()
        invariant k <= a.len(), paid <= k, from < a.len(), d051(a),
        decreases a.len() - k,
    {
        if d060(a, from, k, x) {
            paid = paid + 1;
        }
        k = k + 1;
    }
    paid
}
